        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="GetActiveCall",
                service_name="chatto.api.v1.VoiceCallService",
                input=GetActiveCallRequest,
                output=GetActiveCallResponse,
                idempotency_level=IdempotencyLevel.UNKNOWN,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
